   123→    /// 사용자 모드로 전환 (iretq)
   124→    #[inline]
   125→    pub fn switch_to_user_mode(&self, context: &UserContext) -> ! {
   126→        unsafe {
   127→            // 사용자 모드로 전환하기 위해 iretq 사용
   128→            // 스택에 다음 정보를 쌓음:
   129→            // SS (스택 세그먼트)
   130→            // RSP (스택 포인터)
   131→            // RFLAGS (플래그)
   132→            // CS (코드 세그먼트)
   133→            // RIP (명령어 포인터)
   134→
   135→            use core::arch::asm;
   136→
   137→            asm!(
   138→                "push {data}",      // SS
   139→                "push {rsp}",       // RSP
   140→                "pushf",            // RFLAGS
   141→                "push {code}",      // CS
   142→                "push {rip}",       // RIP
   143→                "iretq",            // 사용자 모드로 전환
   144→                data = in(reg) self.user_segments.data_selector.0,
   145→                rsp = in(reg) context.rsp,
   146→                code = in(reg) self.user_segments.code_selector.0,
   147→                rip = in(reg) context.rip,
   148→                options(noreturn)
   149→            );
   150→        }
   151→    }
